LANGS = ("en", "hi", "mr", "ta", "bn")


def localize(text, lang):
    """Rewrite an English reply in `lang` (en passes straight through)."""
    if not text or (lang or "en")[:2] not in ("hi", "mr", "ta", "bn"):
        return text
    code = lang[:2]
    out = text
    # longest phrases first, so a short phrase cannot eat part of a long one
    table = dict(MORE)
    table.update(PHRASES)
    for en in sorted(table, key=len, reverse=True):
        tr = table[en].get(code)
        if tr and en in out:
            out = out.replace(en, tr)
    for pat, table in PATTERNS:
        tr = table.get(code)
        if tr:
            out = re.sub(pat, lambda m, t=tr: t.format(m.group(1)), out)
    # no em dashes anywhere
    out = out.replace("\u2014", "-").replace("\u2013", "-")
    return out


def localize_label(label, lang):
    """A friendly activity name in the chosen language."""
    if not label:
        return label
    key = FAMILY.get(label, label)
    d = ACTIVITY.get(key.lower()) or ACTIVITY.get(label.lower())
    if d:
        return d.get((lang or "en")[:2], label)
    return localize(label, lang)


def localize_time(expr, lang):
    return localize(expr, lang)


def localize_time(expr, lang):
    return localize(expr, lang)


def localize_list(items, lang):
    return [localize(x, lang) for x in (items or [])]
